def _slicer_profile_items(self, context) -> list[tuple[str, str, str]]:
    # Combine the description parts into one string
    desc = (
        "Use the built-in Bambu A1 template. "
        "Add your own profiles in Preferences → Add-ons → 3MF Format → Advanced"
    )
    items = [("NONE", "Built-in default (Bambu A1)", desc)]

    import importlib

    from .threemf_discovery import get_threemf_api

    _api = get_threemf_api()
    if _api is None:
        return items

    sp = importlib.import_module(".slicer_profiles", package=_api.__package__)
    for p in sp.list_profiles():
        detail = p.machine or p.vendor
        desc = (
            f"{detail} (from {p.source_file}). "
            "Add more profiles in Preferences → Add-ons → 3MF Format → Advanced"
        )
        items.append((p.name, p.name, desc))

    return items


def get_special_blend_items(self, context):
    # puzzles.blend itself (the hand-crafted jigsaw/sliding-puzzle templates)
    # stays Premium-exclusive and is stripped from free builds by build.py --
    # unlike the interactive Jigsaw Puzzle Generator, which is free. Items must be a
    # callback (not a static default) so this list can change per-build.
    #
    # Dynamic-items EnumProperty can't take an explicit `default=` -- Blender
    # always initializes to whichever item comes first here. Putting
    # puzzles.blend first for Premium preserves the original default; free
    # builds fall back to holder.blend since puzzles.blend isn't an option.
    if temp.PREMIUMVERSION:
        return [
            ("puzzles.blend", "Jigzaw/Sliding Puzzles", "global"),
            ("holder.blend", "Map Holder", "Latitudes -60 to 60"),
            (
                "connectors.blend",
                "Map Connectors",
                "Continental USA, Hawaii, parts of Alaska",
            ),
        ]
    return [
        ("holder.blend", "Map Holder", "Latitudes -60 to 60"),
        (
            "connectors.blend",
            "Map Connectors",
            "Continental USA, Hawaii, parts of Alaska",
        ),
    ]


def generation_mode_update(self, context):
    self.use_multi_generation = self.generation_mode == "MULTI"


def _get_tex_use_texture(self):
    # Runs each time the value is read; falls back to temp.has3mf
    # only if the user hasn't explicitly set it.
    return self.get("tex_use_texture", bool(temp.has3mf))


def _set_tex_use_texture(self, value):
    self["tex_use_texture"] = value


