_ROAD_TYPE_IDS = {d[0] for d in ROAD_TYPE_DEFS}


class TP3D_RoadTypeItem(bpy.types.PropertyGroup):
    """One row of the Roads UIList. `name` (inherited) holds the translated
    display label; `road_id` is the stable, untranslated lookup key."""

    road_id: StringProperty()  # type: ignore
    active: BoolProperty(default=False)  # type: ignore
    description: StringProperty()  # type: ignore


def ensure_road_types(tp3d):
    """Populate/repair `tp3d.road_types` from ROAD_TYPE_DEFS.

    CollectionProperty starts empty on every new file/scene -- unlike an
    EnumProperty there's no static item list Blender can draw on its own, so
    this has to be called before the Roads UIList is drawn (and again after
    file load, in case an older file predates a tier being added/removed).
    Existing values are preserved by road_id; only missing ids are added and
    stale ids (from a future addon downgrade) are dropped.
    """
    existing = {item.road_id: item.active for item in tp3d.road_types}
    if existing.keys() == _ROAD_TYPE_IDS:
        return
    tp3d.road_types.clear()
    for road_id, label, desc in ROAD_TYPE_DEFS:
        item = tp3d.road_types.add()
        item.road_id = road_id
        item.name = label
        item.description = desc
        item.active = existing.get(road_id, False)


def get_road_active(tp3d, road_id: str) -> bool:
    """True if the given road tier (e.g. "highways", "track") is enabled.

    Deliberately NOT tp3d.road_types.get(road_id) -- bpy_prop_collection.get()
    matches by the item's `name` field (the translated display label, e.g.
    "Highways"), not by our separate `road_id` field ("highways"). That
    always misses, silently returning None -- which is why this used to
    return False unconditionally regardless of what was actually checked.
    """
    for item in tp3d.road_types:
        if item.road_id == road_id:
            return bool(item.active)
    return False


def set_road_active(tp3d, road_id: str, value: bool) -> None:
    for item in tp3d.road_types:
        if item.road_id == road_id:
            item.active = bool(value)
            return


def any_road_active(tp3d) -> bool:
    return tp3d.show_roads and any(item.active for item in tp3d.road_types)


def shape_update(self, context):
    """Re-validate the dependent dropdowns against the new shape's matrix.

    Both textLayout and plateMode are dynamic-items EnumProperties whose
    valid set depends on self.shape. Because Blender stores them as a bare
    index, we must re-resolve against the cache string (captured by the
    dedicated update callbacks) rather than re-reading the index, which
    would silently re-interpret it against the new items list.
    """
    valid_layouts = TEXT_LAYOUTS_BY_SHAPE.get(self.shape, ("NONE",))
    valid_plates = PLATE_MODES_BY_SHAPE.get(self.shape, ("NONE",))

    if self.textLayoutCache in valid_layouts:
        self.textLayout = self.textLayoutCache
    else:
        self.textLayout = "NONE"

    if self.plateModeCache in valid_plates:
        self.plateMode = self.plateModeCache
    else:
        self.plateMode = "NONE"


def plate_mode_update(self, context):
    self.plateModeCache = self.plateMode

    if self.plateMode == "SHELL" and not temp.PREMIUMVERSION:
        self.plateMode = "NONE"
        utils.show_message_box(
            _("Shell is a Patreon-exclusive feature."),
            "INFO",
            _("Premium Feature"),
        )
        return

    if self.textLayout not in valid_layouts(self.shape, self.plateMode):
        self.textLayout = "NONE"
        self.textLayoutCache = "NONE"
    
    if self.plateMode == "NONE" and self.textLayout in LAYOUTS_REQUIRING_PLATE:
        # Layout needs a plate to sit on — drop back to no text.
        self.textLayout = "NONE"
        self.textLayoutCache = "NONE"


def text_layout_update(self, context):
    self.textLayoutCache = self.textLayout

    if self.textLayout in LAYOUTS_REQUIRING_PLATE and self.plateMode == "NONE":
        # Auto-upgrade to a solid plate so the layout has something to sit on.
        self.plateMode = "SOLID_PLATE"
        self.plateModeCache = "SOLID_PLATE"


def element_source_update(self, context):
    # ESA WorldCover face-painting (paint_terrain_from_landcover) only runs
    # in PAINT elementMode -- the "Element handling" control is hidden
    # whenever WorldCover is selected (panels.py), so force the stored value
    # to match what that hidden state implies, rather than silently doing
    # nothing if elementMode was last left on SEPARATE/SINGLECOLORMODE_REMESH.
    if self.elementSource == "WORLDCOVER":
        self.elementMode = "PAINT"


