def estimate_map_km(tp3d):
    """Estimate the generated map's real-world km footprint from the cached
    GPX trail bounding box (set by TP3D_OT_pick_gpx_file at file-pick time --
    see utils.io_gpx.compute_gpx_bounds), for the live per-category size
    warnings in the Map Elements section. Returns None when no estimate is
    available (no GPX picked yet, or COORDINATES scale mode, which derives
    its bounds from the scaleLat/scaleLon fields directly rather than the
    trail's own extent).

    Reuses calculate_scale()'s own branch logic rather than re-deriving the
    FACTOR/SCALE formulas here -- see plan Finding 2d: one source of truth
    for "how big is the map", not a second copy that can drift from what
    generation actually computes."""
    if not tp3d.cachedTrailBoundsValid or tp3d.scalemode == "COORDINATES":
        return None
    coordinates = [
        (tp3d.cachedTrailMinLat, tp3d.cachedTrailMinLon),
        (tp3d.cachedTrailMaxLat, tp3d.cachedTrailMaxLon),
    ]
    scale = utils.calculate_scale(tp3d.objSize, coordinates, gen_type=0)
    if not scale:
        return None
    if bpy.app.debug:
        print(
            f"DEBUG: objSize={tp3d.objSize}, scale={scale}, raw_div={tp3d.objSize / scale}"
        )

    return tp3d.objSize / scale  # mm -> real-world km


def update_map_estimate(self, context=None):
    tp3d = getattr(context, "scene", None)
    tp3d = tp3d.tp3d if tp3d else self

    if not tp3d.cachedTrailBoundsValid:
        tp3d.estimated_trail_km = 0.0
        tp3d.estimated_map_km = 0.0
        return

    # 1. Trail Bounds (GPX Extent)
    trail_coords = [
        (tp3d.cachedTrailMinLat, tp3d.cachedTrailMinLon),
        (tp3d.cachedTrailMaxLat, tp3d.cachedTrailMaxLon),
    ]

    # gen_type=2 fits the raw GPX bounds without applying pathScale, so the
    # trail footprint remains stable when the fetched map coverage changes.
    trail_scale = utils.calculate_scale(tp3d.objSize, trail_coords, gen_type=2)
    if trail_scale and trail_scale > 0:
        tp3d.estimated_trail_km = tp3d.objSize / trail_scale
    else:
        tp3d.estimated_trail_km = 0.0

    # The normal factor-mode calculation applies pathScale and therefore
    # estimates the larger terrain area that generation will fetch.
    map_scale = utils.calculate_scale(tp3d.objSize, trail_coords, gen_type=1)
    if map_scale and map_scale > 0:
        tp3d.estimated_map_km = tp3d.objSize / map_scale
    else:
        tp3d.estimated_map_km = 0.0


def repair_invalid_shape(scene):
    """Files/sessions saved before the "... TEXT" shape variants were split
    out into shapeTextStyle may still have `shape` stored as one of those
    now-removed identifiers. Reading an EnumProperty whose stored index no
    longer exists in the (now trimmed, base-shapes-only) items list returns
    '' and logs a bpy.rna warning on every single access -- once per UI
    redraw, so it floods the console. Reset it once to a valid default so
    both the stored value and the warning spam go away."""
    tp3d = getattr(scene, "tp3d", None)
    if tp3d is not None and not tp3d.shape:
        tp3d.shape = "HEXAGON"


